///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name prelistPageSearch
 * @description prelist Page Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistPageSearch = async function () {
    $c.util.getComponent('dma_PrelistPageSearchReq').set('method', "listPrelmInvstgList");
    $c.util.getComponent('dma_PrelistPageSearchReq').set('page', "list");
    await scwin.tx_fn_PrelistPageSearch('listPrelmInvstg.do');
};

/**
 * @method
 * @name goWriteBBS
 * @description go Write BBS 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWriteBBS = async function () {
    $c.util.getComponent('dma_PrelistPageSearchReq').set('method', 'writeCommentLetter');
    const nr = await scwin.tx_fn_goWriteBBS('bbs.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL51310.xml", { "method": 'writeCommentLetter' });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_PrelistPageSearchReq').set('method', 'searchCommentLetterList');
    await scwin.tx_fn_search('bbs.do');
};

/**
 * @method
 * @name searchCommentLetterView
 * @description search Comment Letter View 처리
 * @param {String} contnId contnId
 * @param {String} contnGrpId contnGrpId
 * @param {String} ansObjContnId ansObjContnId
 * @param {String} listInvstgBbsTpCd listInvstgBbsTpCd
 * @param {*} contnAttachSeq contnAttachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCommentLetterView = async function (contnId, contnGrpId, ansObjContnId, listInvstgBbsTpCd, contnAttachSeq) {
    $c.util.getComponent('dma_PrelistPageSearchReq').set('method', 'searchCommentLetterView');
    $c.util.getComponent('dma_PrelistPageSearchReq').set('contnId', contnId);
    $c.util.getComponent('dma_PrelistPageSearchReq').set('contnGrpId', contnGrpId);
    $c.util.getComponent('dma_PrelistPageSearchReq').set('ansObjContnId', ansObjContnId);
    $c.util.getComponent('dma_PrelistPageSearchReq').set('listInvstgBbsTpCd', listInvstgBbsTpCd);
    $c.util.getComponent('dma_PrelistPageSearchReq').set('contnAttachSeq', contnAttachSeq);
    const nr = await scwin.tx_fn_SearchCommentLetterView('bbs.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL51320.xml", { "method": 'searchCommentLetterView', "contnId": contnId, "contnGrpId": contnGrpId, "ansObjContnId": ansObjContnId, "listInvstgBbsTpCd": listInvstgBbsTpCd, "contnAttachSeq": contnAttachSeq });
    }
};
